/**
 * Shader des feux d'artifice.
 *
 * ## L'idee mathematique
 *
 * Un bouquet est un point de depart, un age et une graine. Chaque etincelle
 * en part dans une direction repartie autour du cercle, a une vitesse hachee,
 * et sa position a l'instant t est analytique : la distance parcourue sous
 * une trainee proportionnelle a la vitesse est `v0 (1 - e^{-kt}) / k` — les
 * etincelles ralentissent d'elles-memes — et la gravite retire `g t^2 / 2` a
 * la hauteur. Rien n'est integre d'image en image : chaque fragment resout
 * l'etincelle la ou elle est.
 *
 * L'extinction est une exponentielle de l'age, modulee d'un scintillement
 * rapide de phase propre ; un eclair bref au point de depart marque
 * l'explosion elle-meme.
 *
 * Les bouquets vivent dans un tampon de six emplacements dates par l'horloge
 * du moteur — un depart a -1000 donne un age enorme, donc un bouquet inerte —
 * et un bouquet automatique, tire d'un compteur de periode, part tout seul a
 * un point hache : un ciel qui ne s'anime qu'au clic resterait vide dans la
 * plupart des pages.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le ciel.
 * - `uColorB`, `uColorC` — les deux teintes d'etincelles, melangees par bouquet.
 * - `uClicks` — six bouquets (x, y, temps de depart), tampon circulaire.
 * - `uSparks` — etincelles par bouquet, et donc le cout.
 * - `uGravity` — force de la retombee.
 * - `uDecay` — vitesse d'extinction des etincelles.
 * - `uAuto` — periode des bouquets automatiques, en secondes ; zero les coupe.
 */
export const FIREWORKS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec3 uClicks[6];
uniform float uSparks;
uniform float uGravity;
uniform float uDecay;
uniform float uAuto;

// Nombre pseudo-aleatoire : projection sur une direction arbitraire, sinus
// amplifie, partie fractionnaire.
float feuHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Deux nombres decorreles pour une meme graine.
vec2 feuHash2(vec2 p) {
  return vec2(feuHash(p), feuHash(p + vec2(37.3, 17.7)));
}

// Lumiere qu'un bouquet depose au point p, a l'age donne.
vec3 bouquet(vec2 p, vec2 origine, float age, float graine, int etincelles) {
  // Trop tot ou trop vieux : rien a calculer, et c'est le cas de tous les
  // emplacements vides du tampon.
  if (age < 0.0 || age > 6.0) return vec3(0.0);

  vec3 lumiere = vec3(0.0);
  float teinteBouquet = feuHash(vec2(graine, 3.1));
  float k = 1.6;

  // Bornes constantes : la specification du langage l'exige ; la qualite
  // sort plus tot.
  for (int j = 0; j < 48; j += 1) {
    if (j >= etincelles) break;
    float fj = float(j);
    vec2 h = feuHash2(vec2(fj, graine));

    // Directions reparties sur le cercle, chacune un peu decalee : un bouquet
    // regulier a l'air mecanique, un bouquet aleatoire a des trous.
    float angle = (fj + h.x * 0.8) / float(etincelles) * 6.28318;
    float v0 = 0.22 + 0.25 * h.y;

    float portee = v0 * (1.0 - exp(-k * age)) / k;
    vec2 pos = origine + vec2(cos(angle), sin(angle)) * portee;
    pos.y -= uGravity * age * age * 0.5;

    float d = length(p - pos);
    float size = 0.006 + 0.004 * h.y;
    float noyau = exp(-d * d / (size * size));
    float halo = 0.15 * exp(-d * d / (size * size * 12.0));

    float extinction = exp(-uDecay * age) * (0.75 + 0.25 * sin(age * 25.0 + h.x * 6.28318));
    extinction *= smoothstep(0.0, 0.05, age);

    vec3 teinte = mix(uColorB, uColorC, fract(teinteBouquet + h.y * 0.35));
    lumiere += teinte * (noyau + halo) * extinction;
  }

  // L'eclair de l'explosion : large, bref, au point de depart.
  float d0 = length(p - origine);
  lumiere += uColorC * exp(-d0 * d0 / 0.002) * exp(-age * 12.0) * 2.0;

  return lumiere;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0);
  int etincelles = int(clamp(uSparks, 4.0, 48.0));

  vec3 colour = uColorA;

  for (int i = 0; i < 6; i += 1) {
    vec3 clic = uClicks[i];
    vec2 origine = clic.xy * vec2(aspect, 1.0);
    colour += bouquet(p, origine, uTime - clic.z, clic.z * 7.3 + float(i), etincelles);
  }

  // Le bouquet automatique : un par periode, a un point hache du haut du cadre.
  if (uAuto > 0.0) {
    float periode = max(uAuto, 0.5);
    float index = floor(uTime / periode);
    float ageAuto = uTime - index * periode;
    vec2 origineAuto = vec2(0.2 + 0.6 * feuHash(vec2(index, 1.3)), 0.45 + 0.4 * feuHash(vec2(index, 9.1)));
    colour += bouquet(p, origineAuto * vec2(aspect, 1.0), ageAuto, index * 3.7, etincelles);
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Feux d'artifice : un bouquet eclate a chaque clic et retombe sous la
 * gravite.
 *
 * ## A quoi ce fond reagit
 *
 * Au clic — ou au toucher — sur le cadre : chaque appui date un bouquet dans
 * un tampon circulaire de six emplacements, et les etincelles partent du
 * point exact de l'appui. Le deplacement du pointeur ne change rien.
 *
 * Un bouquet automatique part aussi tout seul, a intervalle regle : un ciel
 * qui n'existe qu'au clic resterait vide dans la plupart des pages. Zero le
 * coupe.
 *
 * ## Le pont clic -> shader
 *
 * Aucun rendu React par image : le tampon est un tableau stable de dix-huit
 * flottants (six fois x, y, temps de depart), mute en place a chaque clic.
 * La surface relit ses uniforms a chaque image, l'identite du tableau ne
 * change pas — la mutation suffit.
 *
 * Le temps ecrit dans le tampon est celui de l'horloge du moteur, memorise par
 * une souscription en priorite d'entree : c'est le meme temps que `uTime` du
 * shader, sans quoi l'age des bouquets serait faux.
 *
 * ## Sous mouvement reduit
 *
 * La surface est refusee par le moteur et le repli statique s'affiche.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { FIREWORKS_FRAGMENT } from './fireworks.shader.js'

/** Ce que l'echappatoire recoit. */
export interface FireworksControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface FireworksOwnProps {
  /** Etincelles par bouquet. @defaultValue 32 */
  sparks?: number
  /** Force de la retombee. @defaultValue 0.25 */
  gravity?: number
  /** Vitesse d'extinction des etincelles. @defaultValue 1.1 */
  decay?: number
  /** Periode des bouquets automatiques, en secondes. Zero les coupe. @defaultValue 2.6 */
  auto?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<FireworksControls>
}

/** Toutes les proprietes. */
export type FireworksProps = Customisable<FireworksOwnProps>

/** Tokens employes par defaut : le ciel, les deux teintes d'etincelles. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-brand-500',
  '--o-palette-amber-200',
] as const

/** Repli par defaut : un ciel fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-t o-from-zinc-50 dark:o-from-zinc-950 o-to-brand-200 dark:o-to-brand-950'

/** Nombre de bouquets vivants a la fois. */
const SLOTS = 6

/**
 * Etincelles par bouquet en qualite basse.
 *
 * Chaque etincelle est une exponentielle et un sinus par fragment, pour
 * chacun des sept bouquets possibles : c'est le seul levier de cout, et il
 * n'a pas besoin d'etre une prop pour etre retrograde.
 */
const LOW_SPARKS = 14

/**
 * Feux d'artifice.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Fireworks className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Fireworks({
  sparks = 32,
  gravity = 0.25,
  decay = 1.1,
  auto = 2.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: FireworksProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Tampon stable, mute en place : six fois (x, y, temps de depart). Un
  // depart a -1000 donne un age enorme, donc un bouquet inerte d'office.
  const uClicks = useRef<number[]>(Array.from({ length: SLOTS * 3 }, () => -1000)).current

  // Le temps de l'horloge du moteur — le meme que uTime du shader. C'est lui
  // qui date les bouquets ; performance.now() donnerait une autre origine.
  const lastTime = useRef(0)

  useEffect(() => {
    const subscription = clock.subscribe(
      ({ time }) => {
        lastTime.current = time
      },
      { priority: CLOCK_PRIORITY.input, name: 'fireworks : horloge' },
    )
    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (host === null) return

    const onDown = (event: PointerEvent): void => {
      const bounds = host.getBoundingClientRect()
      const x = (event.clientX - bounds.left) / Math.max(bounds.width, 1)
      // vUv a son origine en bas : l'axe vertical de l'ecran est inverse.
      const y = 1 - (event.clientY - bounds.top) / Math.max(bounds.height, 1)

      // Tampon circulaire : tout se decale d'un cran, le nouveau bouquet en tete.
      for (let i = SLOTS - 1; i > 0; i -= 1) {
        uClicks[i * 3] = uClicks[(i - 1) * 3] ?? -1000
        uClicks[i * 3 + 1] = uClicks[(i - 1) * 3 + 1] ?? -1000
        uClicks[i * 3 + 2] = uClicks[(i - 1) * 3 + 2] ?? -1000
      }
      uClicks[0] = x
      uClicks[1] = y
      uClicks[2] = lastTime.current
    }

    host.addEventListener('pointerdown', onDown)
    return () => host.removeEventListener('pointerdown', onDown)
  }, [host, uClicks])

  const { ref, setHost: setShaderHost, ready, refused, colours } =
    useTokenShader<HTMLDivElement>({
      fragment: FIREWORKS_FRAGMENT,
      colors,
      uniforms: {
        uClicks,
        uSparks: sparks,
        uGravity: gravity,
        uDecay: decay,
        uAuto: auto,
      },
      name: 'fireworks',
      degrade: (quality) => ({
        uSparks: quality === 'low' ? Math.min(sparks, LOW_SPARKS) : sparks,
      }),
    })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
